begin;
create table public.hh_families(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 100));
create table public.hh_memberships(fid uuid references public.hh_families on delete cascade,uid uuid references auth.users on delete cascade,role text not null check(role in ('admin','adult','child')),primary key(fid,uid));
create table public.hh_invites(code uuid primary key default gen_random_uuid(),fid uuid references public.hh_families on delete cascade,email text not null,role text not null check(role in ('adult','child')),expires timestamptz not null default now()+interval '48 hours');
alter table public.hh_families enable row level security;alter table public.hh_memberships enable row level security;alter table public.hh_invites enable row level security;
revoke all on public.hh_families,public.hh_memberships,public.hh_invites from anon,authenticated;
create function public.hh_my_families() returns table(id uuid,name text,role text) language sql security definer set search_path='' as $$ select f.id,f.name,m.role from public.hh_families f join public.hh_memberships m on m.fid=f.id where m.uid=auth.uid() $$;
create function public.hh_create_family(n text) returns uuid language plpgsql security definer set search_path='' as $$ declare x uuid; begin if auth.uid() is null then raise exception 'Accesso richiesto'; end if; insert into public.hh_families(name) values(trim(n)) returning id into x; insert into public.hh_memberships values(x,auth.uid(),'admin'); return x; end $$;
create function public.hh_members(fid uuid) returns table(uid uuid,email text,role text) language sql security definer set search_path='' as $$ select m.uid,u.email::text,m.role from public.hh_memberships m join auth.users u on u.id=m.uid where m.fid=$1 and exists(select 1 from public.hh_memberships a where a.fid=$1 and a.uid=auth.uid()) $$;
create function public.hh_invite(fid uuid,mail text,r text) returns uuid language plpgsql security definer set search_path='' as $$ declare x uuid; begin if not exists(select 1 from public.hh_memberships m where m.fid=$1 and m.uid=auth.uid() and m.role='admin') then raise exception 'Non autorizzato'; end if; insert into public.hh_invites(fid,email,role) values($1,lower(trim(mail)),r) returning code into x; return x; end $$;
create function public.hh_join(code uuid) returns void language plpgsql security definer set search_path='' as $$ declare i public.hh_invites%rowtype; begin delete from public.hh_invites v where v.code=$1 and v.expires>now() and v.email=(select lower(u.email) from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null) returning * into i; if not found then raise exception 'Invito non valido'; end if; insert into public.hh_memberships values(i.fid,auth.uid(),i.role) on conflict do nothing; end $$;
create function public.hh_revoke(fid uuid,target uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.hh_memberships m where m.fid=$1 and m.uid=auth.uid() and m.role='admin') then raise exception 'Non autorizzato'; end if; delete from public.hh_memberships m where m.fid=$1 and m.uid=target and m.role<>'admin'; end $$;
revoke execute on function public.hh_my_families(),public.hh_create_family(text),public.hh_members(uuid),public.hh_invite(uuid,text,text),public.hh_join(uuid),public.hh_revoke(uuid,uuid) from public,anon;
grant execute on function public.hh_my_families(),public.hh_create_family(text),public.hh_members(uuid),public.hh_invite(uuid,text,text),public.hh_join(uuid),public.hh_revoke(uuid,uuid) to authenticated;
commit;
